INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chouchi','仇池','["仇池","前仇池","氐仇池"]','氐',NULL,'cn','east_asia',296,1,NULL,'year',371,1,NULL,'year',3552,4452,'ochre',NULL,NULL,'前仇池由略阳清水氐杨氏建立。296年杨茂搜率部众据守仇池山地，借险固地势经营地方势力；此后杨氏历代在东晋、汉赵及前秦等强邻之间交涉、称藩或抵抗。杨世死后杨统、杨纂争位，前秦于371年攻取仇池，前仇池政权终结。其地域政权与后来复起的后仇池杨氏相关但并非同一连续君位序列，也不属崔鸿所列十六国。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('ranwei','冉魏','["魏","冉魏"]',NULL,NULL,'cn','east_asia',350,1,NULL,'year',352,12,NULL,'month',4200,4235,'ochre',NULL,NULL,'后赵石虎死后政局崩解，原后赵将领冉闵于350年在邺称帝，国号魏，试图在河北重建政权。冉魏长期受到后赵残部、前燕及其他势力夹击，352年冉闵被前燕擒杀，政权随之灭亡。冉魏仅历一帝，常与十六国时期并论，但不列入崔鸿《十六国春秋》所定十六国。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xiliang','西梁','["梁","后梁","萧梁"]',NULL,NULL,'cn','east_asia',555,2,NULL,'month',587,10,NULL,'month',6661,7053,'ochre',NULL,'nan-chao','西魏攻陷江陵、梁元帝被杀后，西魏于555年扶立萧詧为梁主，江陵成为依附西魏的缓冲政权。西梁沿用梁制，疆域狭小，历萧詧、萧巋、萧琮三代；先后依附西魏、北周并与隋通婚。587年隋文帝召萧琮入朝并废国，西梁并入隋。它延续了梁的皇室名号与礼制，但政治自主受到宗主国限制。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xiyan','西燕','["燕"]','慕容鲜卑',NULL,'cn','east_asia',384,1,NULL,'year',394,1,NULL,'year',4608,4728,'ochre',NULL,NULL,'前燕亡于前秦后，慕容泓于384年在关中聚集鲜卑部众起兵，慕容冲继之并于385年据长安称帝。386年迁徙东归途中政变频仍，段随、慕容顗、慕容瑶、慕容忠等相继短暂在位，慕容永最终掌权并定都长子。西燕与后燕争衡至394年，后燕慕容垂攻灭西燕。该政权由前燕宗室复兴运动形成，但内部权力更迭频繁。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sui','段随','xiyan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','西燕将领。386年慕容冲遇害后，韩延拥立段随为燕王；同年慕容恒、慕容永发动政变杀段随，改立慕容顗。段随在位极短，史籍对其身份与具体经历记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段隨"}]',NULL,NULL,'西燕皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-chong','慕容冲','xiyan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容泓之弟、前燕宗室，前燕亡后曾受苻坚宠遇。384年在河东起兵，慕容泓死后接掌西燕军队；385年据阿房并称帝，攻取长安。其部众希望东归故地，慕容冲却意在留居关中，386年被韩延所杀，政权随后陷入一年多次更替的内乱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容冲"}]','威皇帝',NULL,'西燕威皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-hao','慕容顗','xiyan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','前燕宗室慕容顗，宜都王慕容桓之子。386年段随被杀后，慕容恒、慕容永拥立他为燕王，改元建明，并率关中鲜卑部众东迁；他很快在内部冲突中被慕容韬杀害，西燕再度易主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/建明_(西燕)"}]',NULL,NULL,'西燕皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-hong','慕容泓','xiyan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','前燕末帝慕容暐之弟，前燕亡后在前秦任北地长史。384年苻坚淝水败后，他在关中召集鲜卑部众起兵，称济北王，成为西燕政权的发端；因执法苛急、威望不及弟慕容冲，同年被部将高盖等杀害，部众改立慕容冲。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容泓"}]',NULL,NULL,'西燕皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-yao','慕容瑶','xiyan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容冲之子。386年西燕东迁途中，部分部众拥立慕容瑶为帝；慕容永随后击败并杀死他，接着拥立慕容泓之子慕容忠。其即位与结局均发生在西燕政权频繁政变之中，史料所载不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容瑶"}]',NULL,NULL,'西燕皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-yong','慕容永','xiyan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容部宗室，通常记为慕容廆弟慕容运之孙。386年参与西燕东迁与政变，先辅佐慕容忠，后在刁云杀忠后称帝，定都长子。慕容永统治西燕至394年，曾与后燕争夺中原；后燕慕容垂攻灭西燕，慕容永被擒杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容永"}]',NULL,NULL,'西燕皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-zhong','慕容忠','xiyan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容泓之子。386年慕容永杀慕容瑶后拥立慕容忠为帝，西燕部众继续向东迁徙，转据长子；慕容忠任用慕容永，后被将领刁云杀害。慕容永继位后，西燕的统治中心与政局趋于稳定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容忠"}]',NULL,NULL,'西燕皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ran-min','冉闵','ranwei','[]',NULL,NULL,NULL,NULL,NULL,NULL,352,6,NULL,'month','["皇帝"]','后赵将领石闵，父冉瞻本姓冉；石虎收养冉瞻后，石闵在后赵军中崛起。349年石虎死后诸子争位，石闵先后废杀石遵、石鉴，350年称帝、复姓冉并建魏，年号永兴。他试图重整邺城政权并与周边势力争战，后赵旧部、前燕及其他势力持续进攻；352年兵败被前燕慕容儁擒杀，冉魏随之覆亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冉闵"}]','平帝',NULL,'魏平帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-cha','萧詧','xiliang','[]',NULL,NULL,519,1,NULL,'year',562,2,NULL,'month','["皇帝"]','梁武帝之孙、萧统第三子，曾任雍州刺史，据襄阳。侯景之乱中与萧绎争夺荆州势力，兄萧誉被萧绎杀害后，转而依附西魏。554年西魏攻陷江陵、杀梁元帝，555年扶立萧詧为梁帝，史称西梁；西魏及其后的北周驻军控制江陵，萧詧统治受限，562年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧詧"}]','宣皇帝','中宗','梁宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-cong','萧琮','xiliang','[]',NULL,NULL,558,1,NULL,'year',607,1,NULL,'year','["皇帝"]','萧巋之子，585年继位为西梁末帝，年号广运。西梁国力受隋控制；587年叔父萧岩等出奔陈朝后，隋文帝召萧琮入朝并废其国，封莒国公。入隋后他历任显职，隋炀帝即位后改封梁公，607年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧琮"}]','孝靖皇帝',NULL,'梁孝靖帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-kui','萧巋','xiliang','[]',NULL,NULL,542,1,NULL,'year',585,5,NULL,'month','["皇帝"]','萧詧之子，562年承袭西梁君位，在位二十三年，改用天保年号。西梁依附西魏、北周，后又与隋保持婚姻和朝贡关系；隋文帝曾为晋王杨广纳其女为妃。萧巋于585年去世，太子萧琮继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧巋"}]','孝明皇帝','世宗','梁明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-chu','杨初','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨氏宗族成员，337年杀杨毅夺取仇池之位，先后与东晋及后赵交涉并受封仇池公、天水公。355年杨毅之弟杨宋奴派人刺杀杨初；杨初之子杨国随即杀宋奴继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨初_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-guo-chouchi','杨国','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨初之子，355年在父亲被杀后诛杀杨宋奴，继承仇池。次年为族中长辈杨俊所杀并取代，杨国在位仅约一年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨国_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-jun-chouchi','杨俊','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨氏宗族长辈，356年杀杨国夺取仇池，接受东晋所授仇池公等封号。其统治约四年，死后由儿子杨世继位；仇池随后仍在东晋与前秦之间维持地方政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨俊_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-maosou','杨茂搜','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','略阳清水氐人，杨氏部落首领杨飞龙的养子。296年关中齐万年之乱时，杨茂搜率部众退保仇池，自称辅国将军、右贤王，收纳流民并建立前仇池统治。其死后由儿子杨难敌承袭，部落事务又由杨难敌与杨坚头分领。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨茂搜"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-nandi','杨难敌','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨茂搜之子，约317年继承仇池部众，与弟杨坚头分领部曲，驻守下辨一带。刘曜进攻时一度避走晋寿，危机解除后返回仇池；他在位期间周旋于汉赵、东晋等势力之间，死后由儿子杨毅继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨难敌"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-shi-chouchi','杨世','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨俊之子，约360年继承仇池，沿袭向东晋称藩并接受封号的做法。前秦扩张期间仇池受其压力；杨世约370年去世后，儿子杨纂继位，而叔父杨统与之争权，削弱了抵御前秦的能力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨世_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-tong-chouchi','杨统','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','前仇池末期杨氏宗室，史料多记为武都太守，并记载他与杨纂争夺权位。371年前秦攻仇池时，杨统率武都部众降秦。不同史料对其是否曾短暂自立及具体继位次序记载不一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨统_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-yi-chouchi','杨毅','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨难敌之子，334年继承仇池势力，向东晋称藩并受封征南将军。仇池内部权力斗争延续，337年被族兄杨初杀害，君位由杨初取得。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨毅_(仇池)"}]',NULL,NULL,'仇池王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-zuan-chouchi','杨纂','chouchi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杨世之子，约370年承袭仇池，曾与叔父杨统争夺权力，并向东晋寻求承认。371年前秦苻坚遣军攻仇池，杨纂在鹫峡战败后投降，被送往长安；前仇池由此结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨纂_(仇池)"}]',NULL,NULL,'仇池王','[]');
